function parseConfig(env) {
  if (env.DEBUG !== undefined && env.DEBUG !== 'true' && env.DEBUG !== 'false') throw new Error('Invalid DEBUG');
  const raw = env.PORT ?? '3000';
  if (!/^[1-9][0-9]{0,4}$/.test(raw) || Number(raw) > 65535) throw new Error('Invalid PORT');
  return { debug: env.DEBUG === 'true', port: Number(raw) };
}

